class Solution {
public:
    string reverseWords(string s) {
        istringstream input(s);
        vector<string> words;
        string word;
        while (input >> word) words.push_back(word);
        reverse(words.begin(), words.end());
        string result;
        for (const string& current : words) {
            if (!result.empty()) result += " ";
            result += current;
        }
        return result;
    }
};
